@RestController
@RequestMapping("/api/v1")
public class OrderController {

    @GetMapping("/orders") // Collection: all orders
    public List<Order> getAllOrders(
        @RequestParam(defaultValue = "0") int page,
        @RequestParam(defaultValue = "20") int size) {
        return orderService.findAll(page, size);
    }

    @GetMapping("/orders/{orderId}") // Single item
    public Order getOrder(@PathVariable Long orderId) {
        return orderService.findById(orderId);
    }

    @GetMapping("/customers/{customerId}/orders") // Nested resource
    public List<Order> getCustomerOrders(@PathVariable Long customerId) {
        return orderService.findByCustomerId(customerId);
    }

    @PostMapping("/orders") // HTTP method is the verb, not the URI
    public Order createOrder(@RequestBody OrderRequest request) {
        return orderService.create(request);
    }
}

@RestController
@RequestMapping("/api/v1/users")
public class UserControllerV1 {

    @GetMapping("/{userId}")
    public UserResponseV1 getUser(@PathVariable Long userId) {
        var user = userService.findById(userId);
        // V1: returns userId as Long
        return new UserResponseV1(user.getId(), user.getName(), user.getEmail());
    }
}

@RestController
@RequestMapping("/api/v2/users") // New version with breaking change
public class UserControllerV2 {

    @GetMapping("/{userId}")
    public UserResponseV2 getUser(@PathVariable String userId) {
        var user = userService.findByUuid(userId);
        // V2: returns userId as UUID string, breaking change
        return new UserResponseV2(user.getUuid(), user.getName(), 
                                   user.getEmail(), user.getCreatedAt());
    }
}

record UserResponseV1(Long userId, String name, String email) {}
record UserResponseV2(String userId, String name, String email, Instant createdAt) {}

@RestController
@RequestMapping("/api/v1/orders")
public class OrderController {

    @GetMapping
    public PagedResponse<Order> getOrders(
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size,
            @RequestParam(defaultValue = "createdAt,desc") String sort) {

        var pageable = PageRequest.of(page, size, Sort.by(sort.split(",")));
        var orderPage = orderRepository.findAll(pageable);

        return new PagedResponse<>(
            orderPage.getContent(),
            orderPage.getTotalElements(),
            orderPage.getTotalPages(),
            orderPage.getNumber(),
            orderPage.getSize()
        );
    }
}

record PagedResponse<T>(List<T> data, long total, int totalPages, 
                         int currentPage, int pageSize) {}

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(MethodArgumentNotValidException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public ErrorResponse handleValidationErrors(MethodArgumentNotValidException ex) {
        var fieldErrors = ex.getBindingResult().getFieldErrors().stream()
            .map(error -> new FieldError(error.getField(), error.getDefaultMessage()))
            .toList();

        return new ErrorResponse(
            "VALIDATION_FAILED",
            "Request validation failed",
            fieldErrors
        );
    }

    @ExceptionHandler(InsufficientBalanceException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public ErrorResponse handleInsufficientBalance(InsufficientBalanceException ex) {
        return new ErrorResponse(
            "INSUFFICIENT_BALANCE",
            "Account balance is insufficient for this transaction",
            null
        );
    }
}

record ErrorResponse(String code, String message, List<FieldError> fieldErrors) {}
record FieldError(String field, String message) {}

@RestController
@RequestMapping("/api/v1/orders")
public class OrderController {

    @GetMapping("/{orderId}")
    public EntityModel<Order> getOrder(@PathVariable Long orderId) {
        var order = orderService.findById(orderId);
        var model = EntityModel.of(order);

        // Add self link
        model.add(linkTo(methodOn(OrderController.class)
            .getOrder(orderId)).withSelfRel());

        // Add conditional action links based on order state
        if (order.getStatus() == OrderStatus.PENDING) {
            model.add(linkTo(methodOn(OrderController.class)
                .cancelOrder(orderId)).withRel("cancel"));
        }

        if (order.getStatus() == OrderStatus.SHIPPED) {
            model.add(linkTo(methodOn(OrderController.class)
                .returnOrder(orderId)).withRel("return"));
        }

        return model; // Returns order data + hypermedia links
    }
}
